package audio

import (
	_ "embed"
	"log/slog"
	"time"
)

// EventBootVoice is the spoken "rex" announcement (lifeOS boot voice). It is
// independent of the soundset: the PCM is a fixed embedded asset generated by
// voice/gen.sh (macOS `say` + ffmpeg), not synthesized from a catalog.
//
// Played right after the startup tone so the two never overlap; gated by
// Config.BootVoice / SetBootVoice in addition to the usual enabled + volume.
const EventBootVoice = "boot_voice"

// bytesPerFrame is the size of one PCM frame (int16 × channels).
const bytesPerFrame = 2 * channels

//go:embed voice/rex.pcm
var bootVoicePCM []byte

// SetBootVoice toggles the boot voice announcement.
func (p *Player) SetBootVoice(b bool) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.cfg.BootVoice = b
	slog.Info("audio: boot voice toggled", "enabled", b)
}

// pcmDuration returns the playback length of s16le PCM at sampleRate.
func pcmDuration(pcm []byte) time.Duration {
	return time.Duration(len(pcm)/bytesPerFrame) * time.Second / sampleRate
}

// playBootVoice schedules the voice after the startup tone finishes. Caller
// must not hold p.mu.
func (p *Player) playBootVoice() {
	p.mu.Lock()
	on := p.enabled && p.cfg.Enabled && p.cfg.BootVoice
	delay := pcmDuration(p.pcm[EventStartup])
	p.mu.Unlock()
	if !on {
		slog.Debug("audio: boot voice skipped", "reason", "disabled")
		return
	}
	slog.Info("audio: boot voice scheduled", "delay", delay, "len", pcmDuration(bootVoicePCM))
	time.AfterFunc(delay, func() { p.playPCM(EventBootVoice, bootVoicePCM) })
}
